<h1 class="h4 fw-bold mb-3">Orders</h1>
<form class="row g-2 mb-3"><div class="col-md-4"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Order no, name or email" aria-label="Search orders"></div>
<div class="col-md-3"><select class="form-select" name="status" aria-label="Status"><option value="">All statuses</option><?php foreach (['pending_payment', 'placed', 'processing', 'packed', 'shipped', 'out_for_delivery', 'delivered', 'cancelled'] as $s): ?><option value="<?= $s ?>" <?= $status === $s ? 'selected' : '' ?>><?= e(status_label($s)) ?></option><?php endforeach; ?></select></div><div class="col-auto"><button class="btn btn-dark">Filter</button></div></form>
<div class="table-responsive bg-white rounded-3 shadow-sm"><table class="table table-hover align-middle mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Payment</th><th>Status</th><th class="text-end">Total</th></tr></thead><tbody>
<?php foreach ($orders as $o): ?><tr><td><a href="<?= e(url('admin/orders/' . $o['order_no'])) ?>"><?= e($o['order_no']) ?></a></td><td><?= e($o['customer_name']) ?><div class="small text-muted"><?= e($o['customer_email']) ?></div></td><td class="small"><?= e(date('j M Y', strtotime($o['created_at']))) ?></td><td><?= status_badge($o['payment_status']) ?><div class="small text-muted"><?= e($o['payment_method']) ?></div></td><td><?= status_badge($o['order_status']) ?></td><td class="text-end"><?= e(inr($o['total'])) ?></td></tr><?php endforeach; ?>
<?php if (!$orders): ?><tr><td colspan="6" class="text-muted text-center py-4">No orders found.</td></tr><?php endif; ?></tbody></table></div>
<?php partial('pager', ['page' => $page, 'pages' => $pages]); ?>
